@Service
public class TopicCacheService {
    private final StringRedisTemplate redis;
    private final ObjectMapper json;
    private final TopicRepository repository;

    public TopicCacheService(StringRedisTemplate redis, ObjectMapper json, TopicRepository repository) {
        this.redis = redis;
        this.json = json;
        this.repository = repository;
    }

    public TopicDetail get(String slug) throws Exception {
        String key = "topic:slug:" + slug;
        String cached = redis.opsForValue().get(key);
        if (cached != null) {
            return json.readValue(cached, TopicDetail.class);
        }
        String lockKey = key + ":rebuild";
        Boolean locked = redis.opsForValue().setIfAbsent(lockKey, "1", Duration.ofSeconds(10));
        if (Boolean.TRUE.equals(locked)) {
            try {
                TopicDetail detail = repository.findPublished(slug).orElseThrow();
                redis.opsForValue().set(key, json.writeValueAsString(detail), Duration.ofMinutes(5));
                return detail;
            } finally {
                redis.delete(lockKey);
            }
        }
        Thread.sleep(50);
        String retry = redis.opsForValue().get(key);
        return retry != null ? json.readValue(retry, TopicDetail.class)
                : repository.findPublished(slug).orElseThrow();
    }
}

@Component
public class RedisLock {
    private static final DefaultRedisScript<Long> UNLOCK = new DefaultRedisScript<>(
            "if redis.call('get', KEYS[1]) == ARGV[1] then "
                    + "return redis.call('del', KEYS[1]) else return 0 end", Long.class);

    private final StringRedisTemplate redis;

    public RedisLock(StringRedisTemplate redis) {
        this.redis = redis;
    }

    public String tryLock(String key, Duration ttl) {
        String token = UUID.randomUUID().toString();
        Boolean ok = redis.opsForValue().setIfAbsent(key, token, ttl);
        return Boolean.TRUE.equals(ok) ? token : null;
    }

    public boolean unlock(String key, String token) {
        Long removed = redis.execute(UNLOCK, List.of(key), token);
        return removed != null && removed > 0;
    }
}
